head.script:
scwin.onpageload = function() {
	imports("uiplugin.popup");
};

scwin.fn_openPopup = function() {
	WebSquare.util.openPopup("/sample/common_link/p_popup_WPF-1754_(WSQ-2874)_Sample.xml", {
		id: "pop1",
		type: "litewindow",
		width: 500,
		height: 500,
		top: 50,
		left: 50,
		popupName: "test",
		modal: true,
		useIFrame: false,
		resizable: false,
		status: false,
		menubar: false,
		scrollbars: scroll,
		title: false
	});
};

scwin.trigger1_onclick = function(e) {
	scwin.fn_openPopup();
	scwin.fn_openPopup();
};

scwin.clickTrigger = function() {
	if (((j) => j.length ? j : $('#mf__modal'))($('#_modal')).css("display") == "none") {
		(document.getElementById('trigger1') || document.getElementById('mf_trigger1')).click();
	}
};
